function withResource(acquire, release, useFn) {
  const resource = acquire();
  try {
    return useFn(resource);
  } finally {
    release(resource);
  }
}

const log = [];

try {
  withResource(
    () => { log.push('取得連線'); return 'conn'; },
    () => { log.push('釋放連線'); },
    () => { log.push('使用連線時發生錯誤'); throw new Error('連線中斷'); },
  );
} catch (e) {
  log.push(`捕捉到例外：${e.message}`);
}

console.log(log);

